from pathlib import Path
Path('system').mkdir(exist_ok=True)
Path('system/controlDict').write_text('''FoamFile { format ascii; class dictionary; object controlDict; }
application snappyHexMesh;
startFrom startTime; startTime 0; stopAt endTime; endTime 1; deltaT 1; writeControl timeStep; writeInterval 1;
''')
Path('system/blockMeshDict').write_text('''FoamFile { format ascii; class dictionary; object blockMeshDict; }
scale 1;
vertices ((-0.024 -0.024 -0.006) (0.024 -0.024 -0.006) (0.024 0.024 -0.006) (-0.024 0.024 -0.006) (-0.024 -0.024 0.006) (0.024 -0.024 0.006) (0.024 0.024 0.006) (-0.024 0.024 0.006));
blocks (hex (0 1 2 3 4 5 6 7) (48 48 12) simpleGrading (1 1 1));
edges ();
boundary (background { type patch; faces ((0 4 7 3) (1 2 6 5) (0 1 5 4) (3 7 6 2) (0 3 2 1) (4 5 6 7)); });
mergePatchPairs ();
''')
Path('system/snappyHexMeshDict').write_text('''FoamFile { format ascii; class dictionary; object snappyHexMeshDict; }
castellatedMesh true; snap true; addLayers false;
geometry
{
 outer_ring_wetted.stl { type triSurfaceMesh; name outer_ring_wetted; }
 spinner_wetted.stl { type triSurfaceMesh; name spinner_wetted; }
 ring_end_top.stl { type triSurfaceMesh; name ring_end_top; }
 ring_end_bottom.stl { type triSurfaceMesh; name ring_end_bottom; }
}
castellatedMeshControls
{
 maxLocalCells 300000; maxGlobalCells 500000; minRefinementCells 0; maxLoadUnbalance 0.10; nCellsBetweenLevels 1;
 features ();
 refinementSurfaces
 {
  outer_ring_wetted { level (1 1); patchInfo { type wall; } }
  spinner_wetted { level (1 1); patchInfo { type wall; } }
  ring_end_top { level (1 1); patchInfo { type wall; } }
  ring_end_bottom { level (1 1); patchInfo { type wall; } }
 }
 resolveFeatureAngle 30; refinementRegions {}; locationInMesh (0 0 0); allowFreeStandingZoneFaces true;
}
snapControls { nSmoothPatch 5; tolerance 1.5; nSolveIter 50; nRelaxIter 5; nFeatureSnapIter 10; implicitFeatureSnap false; explicitFeatureSnap false; multiRegionFeatureSnap false; }
addLayersControls { relativeSizes true; layers {}; expansionRatio 1.0; finalLayerThickness 0.3; minThickness 0.1; nGrow 0; featureAngle 60; nRelaxIter 3; nSmoothSurfaceNormals 1; nSmoothNormals 3; nSmoothThickness 10; maxFaceThicknessRatio 0.5; maxThicknessToMedialRatio 0.3; minMedialAxisAngle 90; nBufferCellsNoExtrude 0; nLayerIter 50; }
meshQualityControls { maxNonOrtho 70; maxBoundarySkewness 20; maxInternalSkewness 4; maxConcave 80; minVol 1e-18; minTetQuality 1e-20; minArea -1; minTwist 0.02; minDeterminant 0.001; minFaceWeight 0.02; minVolRatio 0.01; minTriangleTwist -1; nSmoothScale 4; errorReduction 0.75; relaxed { maxNonOrtho 75; } }
writeFlags (scalarLevels); mergeTolerance 1e-6;
''')
print('Wrote controlDict, blockMeshDict, snappyHexMeshDict')

Path('system/fvSchemes').write_text('''FoamFile { format ascii; class dictionary; object fvSchemes; }
ddtSchemes { default steadyState; }
gradSchemes { default Gauss linear; }
divSchemes { default none; }
laplacianSchemes { default Gauss linear corrected; }
interpolationSchemes { default linear; }
snGradSchemes { default corrected; }
''')
Path('system/fvSolution').write_text('''FoamFile { format ascii; class dictionary; object fvSolution; }
solvers {}
''')
print('Added mesh-utility fvSchemes and fvSolution')
